head.script:
scwin.fr_SecuGrpId;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.clickBzProcsNo;
scwin.clickListProcsStatCd;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top);
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        const vCurMonth = $c.ut.cGetMinusMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 2);
        edt_BzSDate.setValue(vCurMonth);
        edt_BzEDate.setValue(vCurDate);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
        await scwin.setCode();
        // fn_Search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05980.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name cmb_DEP_CD_onselchange
 * @description cmb_DEP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_DEP_CD_onselchange = function() {
    try {
        scwin.gDepCd = cmb_DEP_CD.getValue();
        if (scwin.gDepCd === '') {
            cmb_EMP_NO.setValue('');
        }
        dts_EMP_NO.UseFilter = true;
        dts_EMP_NO.Filter();
        dts_EMP_NO.sort("DEP_CD", 0);
        // dts_EMP_NO.sort(); // W-Craft 주석처리
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05980.cmb_DEP_CD_onselchange" });
    }
};

/**
 * @method
 * @name dts_DEP_CD_OnLoadCompleted
 * @description dts_DEP_CD 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DEP_CD_OnLoadCompleted = function(rowcount) {
    try {
        cmb_DEP_CD.setValue(js_dep_cd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05980.dts_DEP_CD_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_DEP_CD_OnLoadError
 * @description dts_DEP_CD 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DEP_CD_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_DEP_CD);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05980.dts_DEP_CD_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_EMP_NO_OnLoadCompleted
 * @description dts_EMP_NO 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
