 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05980.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF05980.xml", SCREN_PROCS_TP_CD_07);
        scwin.excelDown();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05980.btn_Excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_DEP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_DEP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_EMP_NO",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_EMP_NO=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_dts_FORM_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_FORM_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions4 = {
        id : "sbm_dts_LIST_BZ_TP_CD",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_LIST_BZ_TP_CD=body.content",
        isProcessMsg : false
    };

    const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
    // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    cmb_DEP_CD.setValue(js_dep_cd);
    cmb_EMP_NO.setValue(js_emp_no);
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&method=searchSpacReleasAct";
    url += "&inputMessageId=SPACRELEAS_MST_INOUT";
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&PROCS_STAT_CD=" + rdo_PROCS_STAT_CD.getValue();
    url += "&LIST_BZ_PROCS_STA=" + edt_BzSDate.getValue();
    url += "&LIST_BZ_PROCS_END=" + edt_BzEDate.getValue();
    url += "&DEP_CD=" + cmb_DEP_CD.getValue();
    url += "&EMP_NO=" + cmb_EMP_NO.getValue();
    // url += "&UP_DEP_CD=" + js_belngdepcd;
    // url += "&LD_MKT_TP_CD="+gLdMktTp;
    // alert("vListMdCd :"+vListMdCd);
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/administrativeIssue.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue();
    arrPar[1] = txb_COM_NM.getValue();
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
    txb_COM_NM.setValue(arrPar[0].COM_NM);
};

/**
 * @method
 * @name setContnId
 * @description set Contn Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    if (Number(obj) > 0) {
        // 그리드에서 선택시
        scwin.clickBzProcsNo = dts_List.getCellData(Number(obj), "BZ_PROCS_NO");
        if (dts_List.getCellData(Number(obj), "PROCS_STAT_NM") === "접수") {
            scwin.clickListProcsStatCd = "10";
        }
    } else {
        scwin.clickBzProcsNo = "";
        scwin.clickListProcsStatCd = "";
    }
};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row) {
    scwin.setContnId(row);
    if (row < 0) {
        // 그리드에서 선택시
        scwin.clickBzProcsNo = ""; // 초기화

    }
    const hight = "290";
    const pageNM = "ULDSTF05981";
    const options = {
        id: "" + pageNM + "",
        title: "SPAC해제조치",
        type: "browserPopup",
        width: "745px",
        height: hight,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/lstproc/" + pageNM + ".gfm", options);
};

/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    $c.data.downloadGridViewExcel(grd_List, {fileName: "SPAC해제조치", type: "2"}); //

};
